#include <string.h>

/**
Given a string, return a duplicate of the string. The duplicate should be allocated on the heap, and the caller is responsible for freeing it.

@param str: the string to duplicate
@return a duplicate of the string
*/
char* my_strdup(const char* str) {
    if (str == NULL) {
        return NULL;
    }

    // Calculate the length of the string, including the null terminator.
    // This is a safe operation as strlen is designed to handle valid C strings.
    size_t len = strlen(str) + 1;

    // Allocate memory on the heap for the duplicate string.
    // malloc can return NULL if memory allocation fails.
    char* duplicate = (char*)malloc(len);

    // Check if memory allocation was successful.
    if (duplicate == NULL) {
        // If allocation failed, return NULL to indicate failure.
        return NULL;
    }

    // Copy the string content, including the null terminator, to the allocated memory.
    // memcpy is used here for efficiency and to ensure the null terminator is copied.
    memcpy(duplicate, str, len);

    // Return the pointer to the newly allocated and duplicated string.
    return duplicate;
}
